create table wksp_mlegenai.sm_posts (
    id           number generated by default on null as identity not null enable,
    post_comment varchar2(4000 char),
    file_blob    blob,
    file_mime    varchar2(255 char),
    file_name    varchar2(255 char),
    lat          number,
    lon          number,
    created      date not null enable,
    created_by   varchar2(255 char) not null enable,
    updated      date not null enable,
    updated_by   varchar2(255 char) not null enable,
    ai_output    varchar2(1000 byte),
    ai_output_td varchar2(4000 byte),
    exif_data    json
);

alter table wksp_mlegenai.sm_posts
    add constraint sm_posts_id_pk primary key ( id )
        using index enable;


